"""Testable OpenCV video reader without ROS dependencies."""

from dataclasses import dataclass
from pathlib import Path
import cv2


def resize_frame(frame, width: int, height: int):
    if width <= 0 or height <= 0:
        raise ValueError("output dimensions must be positive")
    if frame is None or frame.ndim != 3 or frame.shape[2] != 3:
        raise ValueError("decoded frame must be a three-channel image")
    return cv2.resize(frame, (width, height), interpolation=cv2.INTER_AREA)


@dataclass(frozen=True)
class VideoMetadata:
    path: Path
    width: int
    height: int
    fps: float
    frame_count: int
    duration_sec: float
    codec: str


def validate_playback_parameters(path: Path, playback_rate: float,
                                 start_frame: int) -> None:
    if not path.is_file():
        raise FileNotFoundError(f"video file does not exist: {path}")
    if playback_rate <= 0.0:
        raise ValueError("playback_rate must be greater than zero")
    if start_frame < 0:
        raise ValueError("start_frame must be non-negative")


class VideoReader:
    def __init__(self, path: Path, start_frame: int = 0, loop: bool = False,
                 capture_factory=cv2.VideoCapture):
        self.path = Path(path).expanduser().resolve()
        self.loop = bool(loop)
        self._capture = capture_factory(str(self.path))
        if not self._capture.isOpened():
            self._capture.release()
            raise RuntimeError(f"OpenCV cannot open video: {self.path}")
        self.metadata = self._read_metadata()
        if start_frame >= self.metadata.frame_count:
            self.close()
            raise ValueError(
                f"start_frame {start_frame} is outside {self.metadata.frame_count} frames")
        self.start_frame = int(start_frame)
        self.frame_index = self.start_frame
        self.eof = False
        self._seek(self.start_frame)

    def _read_metadata(self) -> VideoMetadata:
        width = int(round(self._capture.get(cv2.CAP_PROP_FRAME_WIDTH)))
        height = int(round(self._capture.get(cv2.CAP_PROP_FRAME_HEIGHT)))
        fps = float(self._capture.get(cv2.CAP_PROP_FPS))
        frame_count = int(round(self._capture.get(cv2.CAP_PROP_FRAME_COUNT)))
        if width <= 0 or height <= 0:
            self.close()
            raise ValueError("video dimensions must be positive")
        if fps <= 0.0:
            self.close()
            raise ValueError("video FPS must be positive")
        if frame_count <= 0:
            self.close()
            raise ValueError("video frame count must be positive")
        code = int(self._capture.get(cv2.CAP_PROP_FOURCC))
        codec = "".join(chr((code >> (8 * index)) & 0xFF) for index in range(4))
        return VideoMetadata(self.path, width, height, fps, frame_count,
                             frame_count / fps, codec.strip("\x00"))

    def _seek(self, frame_index: int) -> None:
        if not self._capture.set(cv2.CAP_PROP_POS_FRAMES, float(frame_index)):
            raise RuntimeError(f"cannot seek video to frame {frame_index}")

    def seek(self, frame_index: int) -> None:
        if frame_index < self.start_frame or frame_index >= self.metadata.frame_count:
            raise ValueError(f"frame index is outside playback range: {frame_index}")
        self._seek(frame_index)
        self.frame_index = int(frame_index)
        self.eof = False

    def skip_to(self, frame_index: int) -> None:
        """Discard sequential compressed frames without materializing images."""
        if frame_index < self.frame_index:
            self.seek(frame_index)
            return
        while self.frame_index < frame_index:
            if not self._capture.grab():
                self.eof = True
                raise RuntimeError(f"cannot skip to video frame {frame_index}")
            self.frame_index += 1

    def read(self):
        ok, frame = self._capture.read()
        if ok:
            index = self.frame_index
            self.frame_index += 1
            return index, frame
        if not self.loop:
            self.eof = True
            return None
        self._seek(self.start_frame)
        self.frame_index = self.start_frame
        ok, frame = self._capture.read()
        if not ok:
            raise RuntimeError("video read failed after loop seek")
        index = self.frame_index
        self.frame_index += 1
        return index, frame

    def close(self) -> None:
        if self._capture is not None:
            self._capture.release()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()
